namespace ShotOut {
static partial class Art {
    internal static bool SavedGeneralImageSettings(Mark image){return image.Exposure!=0||image.Contrast!=0||image.Brightness!=0||image.Saturation!=0||image.Temperature!=0;}
    internal static List<string> ImageEffectDisplayOrder(Mark image){
        var valid=new List<string>();if(SavedGeneralImageSettings(image))valid.Add("General");if(image.ImageFilter>0)valid.Add("Filter");foreach(var zone in image.ImageZones)valid.Add("Zone:"+zone.Id);valid.Reverse();var saved=(image.ImageEffectOrder??new List<string>()).Where(valid.Contains).Distinct().ToList();return valid.Where(key=>!saved.Contains(key)).Concat(saved).ToList();
    }
    static bool SameImageEffectOrder(Mark first,Mark second){return first!=null&&(first.ImageEffectOrder??new List<string>()).SequenceEqual(second.ImageEffectOrder??new List<string>());}
    static ColorMatrix OrderedToneMatrix(Mark image,List<string> stages){
        if(stages.Count==1)return ImageAdjustmentMatrix(image,stages[0]=="Filter",stages[0]=="General");if(stages[0]=="General")return ImageAdjustmentMatrix(image);
        var filter=ImageAdjustmentMatrix(image,true,false);var general=ImageAdjustmentMatrix(image,false,true);var result=new float[5][];for(int i=0;i<5;i++){result[i]=new float[5];for(int j=0;j<5;j++)for(int k=0;k<5;k++)result[i][j]+=filter[i,k]*general[k,j];}return new ColorMatrix(result);
    }
    static Bitmap BuildOrderedImageEffects(Bitmap source,Mark image,Rectangle area,bool compared){
        Bitmap current=null;try{
            if(area!=new Rectangle(Point.Empty,source.Size))current=source.Clone(area,PixelFormat.Format32bppArgb);
            if(!compared){var pending=new List<string>();Action flush=delegate{if(pending.Count==0)return;var next=BuildImageTone(current??source,OrderedToneMatrix(image,pending));if(current!=null)current.Dispose();current=next;pending.Clear();};
                foreach(string key in ImageEffectDisplayOrder(image).AsEnumerable().Reverse()){
                    if(key=="General"){if(image.ImageAdjustmentsEnabled&&image.AdjustmentStrength>0)pending.Add(key);}
                    else if(key=="Filter"){if(HasImageFilter(image))pending.Add(key);}
                    else {var zone=image.ImageZones.FirstOrDefault(item=>key=="Zone:"+item.Id);if(!ActiveZone(zone)||ZoneCompared(image,zone))continue;flush();if(current==null)current=source.Clone(area,PixelFormat.Format32bppArgb);PaintImageZone(current,zone,area,source.Size,area.Location);}
                }flush();
            }
            return current??source.Clone(area,PixelFormat.Format32bppArgb);
        }catch{if(current!=null)current.Dispose();throw;}
    }
}
partial class Editor {
    ImageEffectRow effectDragCandidate,effectDragging;
    Point effectMouseDown;
    bool BeginEffectDrag(MouseEventArgs e){if(e.Button!=MouseButtons.Left||effectDragCandidate==null)return false;if(Math.Abs(e.X-effectMouseDown.X)<SystemInformation.DragSize.Width/2&&Math.Abs(e.Y-effectMouseDown.Y)<SystemInformation.DragSize.Height/2)return false;effectDragging=effectDragCandidate;effectDragCandidate=null;try{layers.DoDragDrop("ShotOutImageEffect",DragDropEffects.Move);}finally{effectDragging=null;layerInsertion=-1;layers.Invalidate();}return true;}
    internal bool HandleImageEffectMove(MouseEventArgs e){return BeginEffectDrag(e);}
    internal bool HandleImageEffectUp(MouseEventArgs e){if(effectDragCandidate==null)return false;var row=effectDragCandidate;effectDragCandidate=null;if(e.Button==MouseButtons.Left)OpenImageEffectRow(row);return true;}
    int EffectDropGap(Point point){if(effectDragging==null)return -1;int parent=layers.Items.IndexOf(effectDragging.ParentImage),end=parent+1;while(end<layers.Items.Count&&layers.Items[end] is ImageEffectRow&&((ImageEffectRow)layers.Items[end]).ParentImage==effectDragging.ParentImage)end++;int index=layers.IndexFromPoint(point);if(index<0)return -1;var rect=layers.GetItemRectangle(index);int gap=index+(point.Y>=rect.Top+rect.Height/2?1:0);return gap>=parent+1&&gap<=end?gap:-1;}
    bool HandleEffectDragOver(DragEventArgs e){if(effectDragging==null)return false;int gap=EffectDropGap(layers.PointToClient(new Point(e.X,e.Y)));e.Effect=gap<0?DragDropEffects.None:DragDropEffects.Move;if(gap!=layerInsertion){layerInsertion=gap;layers.Invalidate();}return true;}
    bool HandleEffectDrop(DragEventArgs e){if(effectDragging==null)return false;int gap=EffectDropGap(layers.PointToClient(new Point(e.X,e.Y)));if(gap>=0)ReorderImageEffect(effectDragging,gap);layerInsertion=-1;layers.Invalidate();return true;}
    void ReorderImageEffect(ImageEffectRow row,int gap){
        if(!Marks.Contains(row.ParentImage))return;var order=Art.ImageEffectDisplayOrder(row.ParentImage);int start=layers.Items.IndexOf(row.ParentImage)+1,old=order.IndexOf(row.Effect),target=gap-start;if(old<0)return;if(target>old)target--;target=Math.Max(0,Math.Min(order.Count-1,target));if(target==old)return;Push();order.RemoveAt(old);order.Insert(target,row.Effect);row.ParentImage.ImageEffectOrder=order;selectedEffectRow=row;View.InvalidateMarkupCache();RefreshImage();
    }
