        CanvasDownWithModifiers(mouse(350,220),Keys.None);CanvasMove(mouse(355,225));float imageXBeforeRelease=pasted.X;var position=mouse(400,260);CanvasMove(new MouseEventArgs(MouseButtons.None,0,position.X,position.Y,0));CanvasMove(new MouseEventArgs(MouseButtons.None,0,position.X+30,position.Y+30,0));check(!moving&&!dragging&&!resizing&&pasted.X==imageXBeforeRelease,"Losing the mouse button ends a drag instead of leaving objects attached to the cursor");OpenTransformControls();BeginTransformSizing(true);SetTool("Arrow");CanvasDownWithModifiers(mouse(20,20),Keys.None);CanvasMove(mouse(70,50));CanvasUp(mouse(70,50));check(!transformSizeActive&&!transformSizeDragging&&Marks.Last().Kind=="Arrow","Leaving Transform sizing clears its drag state before annotation tools run");
