        using(var source=Blank(200,160)){using(var graphics=Graphics.FromImage(source))graphics.Clear(Color.FromArgb(80,120,180));LoadImageDocument(new Bitmap(source),"Ordered image effects");}var image=Marks[0];image.Exposure=.2f;image.ImageFilter=3;var zone=new ImageAdjustmentZone {X=.1f,Y=.1f,W=.8f,H=.8f,Feather=0,Settings=new Mark {Exposure=1.3f}};image.ImageZones.Add(zone);RefreshImage();SyncLayers();var zoneRow=layers.Items.Cast<Mark>().OfType<ImageEffectRow>().First(row=>row.Zone==zone);check(((ImageEffectRow)layers.Items[1]).Zone==zone,"Nested rows show the last-applied effect above lower effects");byte[] before;using(var rendered=Art.Render(Background,Marks))before=Art.Bytes(rendered);int count=Marks.Count,history=undo.Count;int filterIndex=layers.Items.Cast<Mark>().ToList().FindIndex(row=>row is ImageEffectRow&&((ImageEffectRow)row).Effect=="Filter");ReorderImageEffect(zoneRow,filterIndex+1);check(Marks.Count==count&&undo.Count==history+1&&image.ImageEffectOrder.SequenceEqual(new[]{"Filter","Zone:"+zone.Id,"General"}),"Dragging a zone below its filter reorders settings in one Undo step without adding layers");
